package fr.formation.hexagonal.adapter.out.persistence;
import fr.formation.hexagonal.application.port.out.*; import fr.formation.hexagonal.domain.*; import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.stereotype.Component;
@Component class RoomPersistenceAdapter implements RoomPort { private final RoomJpa rows; RoomPersistenceAdapter(RoomJpa rows){this.rows=rows;} public Room save(Room r){rows.save(new RoomRow(r.id(),r.name(),r.capacity()));return r;} public Optional<Room> find(UUID id){return rows.findById(id).map(r->new Room(r.id,r.name,r.capacity));} public List<Room> findAll(){return rows.findAll().stream().map(r->new Room(r.id,r.name,r.capacity)).toList();} }
@Component class ReservationPersistenceAdapter implements ReservationPort { private final ReservationJpa rows; ReservationPersistenceAdapter(ReservationJpa rows){this.rows=rows;} public Reservation save(Reservation r){rows.save(ReservationRow.from(r));return r;} public Optional<Reservation> find(UUID id){return rows.findById(id).map(ReservationRow::domain);} public boolean overlaps(UUID roomId,LocalDateTime startsAt,LocalDateTime endsAt){return rows.overlaps(roomId,endsAt,startsAt);} }
interface RoomJpa extends JpaRepository<RoomRow,UUID>{} interface ReservationJpa extends JpaRepository<ReservationRow,UUID>{@org.springframework.data.jpa.repository.Query("select count(r)>0 from ReservationRow r where r.roomId=:roomId and r.status='CONFIRMED' and r.startsAt<:endsAt and r.endsAt>:startsAt")boolean overlaps(UUID roomId,LocalDateTime endsAt,LocalDateTime startsAt);}
@Entity @Table(name="rooms") class RoomRow{@Id UUID id;String name;int capacity;protected RoomRow(){}RoomRow(UUID id,String name,int capacity){this.id=id;this.name=name;this.capacity=capacity;}}
@Entity @Table(name="reservations") class ReservationRow{@Id UUID id;UUID roomId;String organizerEmail;int participants;LocalDateTime startsAt;LocalDateTime endsAt;String status;protected ReservationRow(){}static ReservationRow from(Reservation r){var row=new ReservationRow();row.id=r.id();row.roomId=r.roomId();row.organizerEmail=r.organizerEmail();row.participants=r.participants();row.startsAt=r.startsAt();row.endsAt=r.endsAt();row.status=r.status().name();return row;}Reservation domain(){return new Reservation(id,roomId,organizerEmail,participants,startsAt,endsAt,Reservation.Status.valueOf(status));}}
